def format_human_name(raw_name: str) -> str:
    name = HumanName(raw_name)
    fn = f'{name.first} ' if name.first != '' else ''
    mid = f'{name.middle} ' if name.middle != '' else ''
    ln = name.last
    suf = f' {name.suffix}' if name.suffix != '' else ''
    return f'{fn}{mid}{ln}{suf}'

@dataclass
class Author:
    friendly_name: str | None = None
    key: str | None = None
    remote_ids: dict[str, str] = field(default_factory=dict[str, str])
    birth_date: str | None = None
    death_date: str | None = None

    def __hash__(self):
        return hash((self.friendly_name, self.birth_date, self.death_date))

class ContributorDict(TypedDict):
    name: str
    role: str

@dataclass
class BookRecord:
    langconfig: LangConfig
    wikisource_page_title: str
    title: str | None = None
    subtitle: str | None = None
    publish_date: str | None = None
    edition: str | None = None
    authors: list[Author] = field(default_factory=list)
    illustrators: list[ContributorDict] = field(default_factory=list)
    description: str | None = None
    subjects: list[str] = field(default_factory=list)
    cover: str | None = None
    publishers: list[str] = field(default_factory=list)
    imagename: str | None = None
    categories: list[str] = field(default_factory=list)
    ocaid: str | None = None
    publish_places: list[str] = field(default_factory=list)
    page_count: int | None = None
    wikidata_id: str | None = None
    oclcs: list[str] = field(default_factory=list)
    lccn: str | None = None
    isbn10: str | None = None
    isbn13: str | None = None

    def add_publishers(self, publishers: list[str]) -> None:
        self.publishers = uniq(self.publishers + publishers)

    def add_publish_place(self, places: list[str]) -> None:
        self.publish_places = uniq(self.publish_places + places)

    def add_authors(self, authors: list[Author]) -> None:
        self.authors = uniq(self.authors + authors, key=lambda author: author.friendly_name)

    def add_illustrators(self, illustrators: list[str]) -> None:
        new_illustrators: list[ContributorDict] = [{'name': a, 'role': 'illustrator'} for a in illustrators]
        self.illustrators = uniq(self.illustrators + new_illustrators, key=json.dumps)

    def add_subjects(self, subjects: list[str]) -> None:
        self.subjects = uniq(self.subjects + subjects)

    def add_categories(self, categories: list[str]) -> None:
        self.categories = uniq(self.categories + categories)

    def add_oclcs(self, oclcs: list[str]) -> None:
        self.oclcs = uniq(self.oclcs + oclcs)

    @property
    def wikisource_id(self) -> str:
        return f'{self.langconfig.langcode}:{self.wikisource_page_title}'

    @property
    def source_records(self) -> list[str]:
        records = [f'wikisource:{self.wikisource_id}']
        if self.wikidata_id is not None:
            records.append(f'wikidata:{self.wikidata_id}')
        return records

    def to_dict(self):
        publishers = ['Wikisource']
        publishers.extend(self.publishers)
        output = {'title': self.title, 'source_records': self.source_records, 'identifiers': {'wikisource': [self.wikisource_id]}, 'languages': [self.langconfig.ol_langcode]}
        if self.subtitle is not None:
            output['subtitle'] = self.subtitle
        if self.publish_date is not None:
            output['publish_date'] = self.publish_date
        if self.edition is not None:
            output['edition_name'] = self.edition
        if self.authors:
            output['authors'] = [{'name': author.friendly_name, **({'birth_date': author.birth_date} if author.birth_date else {}), **({'death_date': author.death_date} if author.death_date else {}), **({'remote_ids': author.remote_ids} if author.remote_ids else {}), **({'key': author.key} if author.key else {})} for author in self.authors]
        if self.description is not None:
            output['description'] = self.description
        if self.subjects:
            output['subjects'] = self.subjects
        if self.cover is not None:
            output['cover'] = self.cover
        if publishers:
            output['publishers'] = publishers
        if self.page_count:
            output['number_of_pages'] = self.page_count
        if self.illustrators:
            output['contributors'] = self.illustrators
        return output

def fetch_until_successful(url: str) -> dict:
    for _ in range(5):
        try:
            response = requests.get(url, stream=True)
            return response.json()
        except requests.exceptions.RequestException as error:
            if error.response is None or error.response.status_code in (429, 503):
                time.sleep(10)
            else:
                raise SystemExit(error)
    raise SystemExit(f'could not fetch {url} after 5 tries. You may be rate limited, try again later')

def update_record_with_wikisource_metadata(book: BookRecord, book_id: str, new_data: dict, author_map: dict[str, list[str]]):
    if 'categories' in new_data:
        book.add_categories([cat['title'] for cat in new_data['categories']])
    revision_data = new_data.get('revisions', [])
    infobox = next((d['slots']['main']['*'] for d in revision_data if 'slots' in d and 'main' in d['slots'] and ('*' in d['slots']['main'])), None)
    if infobox is None:
        return
    wikicode = mw.parse(infobox)
    templates = wikicode.filter_templates()
    if not templates:
        return
    template = next((template for template in templates if template.name.strip() == 'header'), None)
    if template is None:
        return
    if book.publish_date is None:
        try:
            yr = template.get('year').value.strip()
            book.publish_date = extract_year(yr)
        except ValueError:
            pass
    if not [b for b in author_map if book_id in author_map[b]] and (not book.authors):
        try:
            author = template.get('author').value.strip()
            if author != '':
                authors = re.split('(?:\\sand\\s|,\\s?)', author)
                if authors:
                    book.add_authors([Author(friendly_name=format_human_name(a)) for a in authors])
        except ValueError:
            pass
    if not book.illustrators:
        try:
            illustrator = template.get('illustrator').value.strip()
            if illustrator != '':
                illustrators = re.split('(?:\\sand\\s|,\\s?)', illustrator)
                if illustrators:
                    book.add_illustrators([format_human_name(a) for a in illustrators])
        except ValueError:
            pass
    if book.description is None:
        try:
            raw = template.get('notes').value.strip()
            raw_spaced = re.sub('(:?<br/>|\\{\\{rule\\}\\})', '\n', raw)
            notes = wtp.remove_markup(raw_spaced)
            if notes != '':
                book.description = notes
        except ValueError:
            pass
    try:
        subject: str = template.get('portal').value.strip()
        if subject != '':
            book.add_subjects(subject.split('/'))
    except ValueError:
        pass

def print_records(records: list[BookRecord]):
    for rec in records:
        if rec.title is None or rec.publish_date is None or len(rec.authors) == 0:
            continue
        r = rec.to_dict()
        print(json.dumps(r))

def scrape_wikisource_api(url: str, imports: dict[str, BookRecord], author_map: dict[str, list[str]]):
    cont_url = url
    while True:
        data = fetch_until_successful(cont_url)
        if 'query' not in data or 'pages' not in data['query']:
            break
        results = data['query']['pages']
        for page in results.values():
            page_identifier = quote(page['title'].replace(' ', '_'))
            key = next((key for key in imports if imports[key].wikisource_page_title == page_identifier), None)
            if not key:
                print(f'{page_identifier} not found in result set')
                continue
            book = imports[key]
            update_record_with_wikisource_metadata(book, key, page, author_map)
        if 'continue' not in data:
            break
        cont_url = update_url_with_params(url, data['continue'])

def update_import_with_wikidata_api_response(impt: BookRecord, book_id: str, obj: Any, author_map: dict[str, list[str]]):
    if 'author' in obj and 'value' in obj['author']:
        author_id = get_wd_item_id(obj['author']['value'])
        if author_id not in author_map:
            author_map[author_id] = []
        author_map[author_id].append(book_id)
    elif 'authorLabel' in obj and 'value' in obj['authorLabel']:
        impt.add_authors([Author(friendly_name=obj['authorLabel']['value'])])
    if 'illustratorLabel' in obj and 'value' in obj['illustratorLabel']:
        impt.add_illustrators([obj['illustratorLabel']['value']])
    if 'publisher' in obj and 'value' in obj['publisher'] or ('publisherName' in obj and 'value' in obj['publisherName']):
        impt.add_publishers([obj['publisherName']['value'] if 'publisherLabel' not in obj else obj['publisherLabel']['value']])
    if 'pageCount' in obj and 'value' in obj['pageCount']:
        impt.page_count = int(obj['pageCount']['value'])
    if 'editionLabel' in obj and 'value' in obj['editionLabel']:
        impt.edition = obj['editionLabel']['value']
    if 'subjectLabel' in obj and 'value' in obj['subjectLabel']:
        impt.add_subjects([obj['subjectLabel']['value']])
    if 'date' in obj and 'value' in obj['date']:
        impt.publish_date = extract_year(obj['date']['value'])
    if 'ocaid' in obj and 'value' in obj['ocaid']:
        impt.ocaid = obj['ocaid']['value']
    if 'publicationPlaceLabel' in obj and 'value' in obj['publicationPlaceLabel']:
        impt.add_publish_place([obj['publicationPlaceLabel']['value']])
    if 'oclcLabel' in obj and 'value' in obj['oclcLabel']:
        impt.add_oclcs([obj['oclcLabel']['value']])
    if 'lccn' in obj and 'value' in obj['lccn']:
        impt.lccn = obj['lccn']['value']
    if 'isbn10' in obj and 'value' in obj['isbn10']:
        impt.isbn10 = obj['isbn10']['value']
    if 'isbn13' in obj and 'value' in obj['isbn13']:
        impt.isbn13 = obj['isbn13']['value']

def scrape_wikidata_api(url: str, cfg: LangConfig, imports: dict[str, BookRecord], author_map: dict[str, list[str]]):
    data = fetch_until_successful(url)
    if 'results' not in data or 'bindings' not in data['results']:
        print('Invalid Wikidata response. Exiting.')
        return
    item_ids = []
    for binding in data['results']['bindings']:
        if 'value' not in binding.get('item', {}):
            print('no value in binding:', binding)
            continue
        item_id = get_wd_item_id(binding['item']['value'])
        item_ids.append(item_id)
        imports[item_id] = BookRecord(wikisource_page_title=quote(binding['page']['value'].replace(' ', '_')), langconfig=cfg, wikidata_id=item_id)
    if not item_ids:
        print('Exiting.')
        return
    for batch in itertools.batched(item_ids, 50):
        query = 'SELECT DISTINCT\n  ?item\n  ?itemLabel\n  ?title\n  ?subtitle\n  ?author\n  ?authorLabel\n  ?illustrator\n  ?illustratorLabel\n  ?publisher\n  ?publisherLabel\n  ?publisherName\n  ?publicationPlaceLabel\n  ?editionLabel\n  ?pageCount\n  ?date\n  ?subjectLabel\n  ?imageUrl\n  ?ocaid\n  ?oclcLabel\n  ?lccn\n  ?isbn10\n  ?isbn13\nWHERE {\n  VALUES ?item {' + ''.join([f'wd:{id}\n    ' for id in batch]) + '}\n  OPTIONAL { ?item wdt:P1476 ?title. }\n  OPTIONAL { ?item wdt:P1680 ?subtitle. }\n  OPTIONAL { ?item wdt:P50 ?author. }\n  OPTIONAL { ?item wdt:P110 ?illustrator. }\n  OPTIONAL { ?item wdt:P123 ?publisher. }\n  OPTIONAL { ?item p:P123/pq:P1932 ?publisherName. }\n  OPTIONAL { ?item wdt:P291 ?publicationPlace. }\n  OPTIONAL { ?item wdt:P393 ?edition. }\n  OPTIONAL { ?item wdt:P577 ?date. }\n  OPTIONAL { ?item wdt:P921 ?subject. }\n  OPTIONAL { ?item wdt:P18 ?image. }\n  OPTIONAL { ?item wdt:P724 ?ocaid. }\n  OPTIONAL { ?item wdt:P1104 ?pageCount. }\n  OPTIONAL { ?item wdt:P243 ?oclc. }\n  OPTIONAL { ?item wdt:P244 ?lccn. }\n  OPTIONAL { ?item wdt:P957 ?isbn10. }\n  OPTIONAL { ?item wdt:P212 ?isbn13. }\n  BIND(CONCAT("https://commons.wikimedia.org/wiki/Special:FilePath/", REPLACE(STR(?image), "^.*[/#]", "")) AS ?imageUrl)\n  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,' + cfg.langcode + '". }\n}'
        metadata_url = update_url_with_params(WIKIDATA_API_URL, {'format': 'json', 'query': query})
        data = fetch_until_successful(metadata_url)
        if 'results' not in data or 'bindings' not in data['results']:
            continue
        ids_for_wikisource_api = []
        results = [obj for obj in data['results']['bindings'] if 'item' in obj and 'value' in obj['item'] and (not (('title' not in obj or 'value' not in obj['title']) and ('itemLabel' not in obj or 'value' not in obj['itemLabel']) or ('title' in obj and 'xml:lang' in obj['title'] and (obj['title']['xml:lang'] != cfg.langcode))))]
        for obj in results:
            title: str = obj['title']['value'] if 'title' in obj and 'value' in obj['title'] else obj['itemLabel']['value']
            subtitle: str | None = obj['subtitle']['value'] if 'subtitle' in obj and 'value' in obj['subtitle'] else None
            book_id = get_wd_item_id(obj['item']['value'])
            impt = imports[book_id]
            impt.title = title
            impt.subtitle = subtitle
            ids_for_wikisource_api.append(impt.wikisource_page_title)
            update_import_with_wikidata_api_response(impt, book_id, obj, author_map)
        for ws_batch in itertools.batched(ids_for_wikisource_api, 50):
            ws_api_url = update_url_with_params(cfg.wikisource_api_url, {'action': 'query', 'titles': '|'.join([unquote(id) for id in ws_batch]), 'prop': 'categories|revisions', 'rvprop': 'content', 'rvslots': 'main', 'cllimit': 'max', 'format': 'json'})
            scrape_wikisource_api(ws_api_url, imports, author_map)
        for obj in results:
            book_id = get_wd_item_id(obj['item']['value'])
            impt = imports[book_id]
            if impt.imagename is None and 'imageUrl' in obj and ('value' in obj['imageUrl']):
                impt.imagename = obj['imageUrl']['value']
                impt.cover = obj['imageUrl']['value']

def fix_contributor_data(imports: dict[str, BookRecord], map: dict[str, list[str]], cfg: LangConfig):
    contributor_ids = list(map.keys())
    for batch in itertools.batched(contributor_ids, 50):
        query = 'SELECT DISTINCT\n  ?contributor\n  ?contributorLabel\n  ?olId\n  ?viaf\n  ?bookbrainz\n  ?musicbrainz\n  ?goodreads\n  ?isni\n  ?imdb\n  ?lc_naf\n  ?librarything\n  ?librivox\n  ?project_gutenberg\n  ?opac_sbn\n  ?amazon\n  ?storygraph\n  ?youtube\n  ?birthDate\n  ?deathDate\nWHERE {\n  VALUES ?contributor {' + ''.join([f'wd:{id}\n    ' for id in batch]) + '}\n  OPTIONAL { ?contributor wdt:P648 ?olId. }\n  OPTIONAL { ?contributor wdt:P214 ?viaf. }\n  OPTIONAL { ?contributor wdt:P2607 ?bookbrainz. }\n  OPTIONAL { ?contributor wdt:P434 ?musicbrainz. }\n  OPTIONAL { ?contributor wdt:P2963 ?goodreads. }\n  OPTIONAL { ?contributor wdt:P213 ?isni. }\n  OPTIONAL { ?contributor wdt:P345 ?imdb. }\n  OPTIONAL { ?contributor wdt:P244 ?lc_naf. }\n  OPTIONAL { ?contributor wdt:P7400 ?librarything. }\n  OPTIONAL { ?contributor wdt:P1899 ?librivox. }\n  OPTIONAL { ?contributor wdt:P1938 ?project_gutenberg. }\n  OPTIONAL { ?contributor wdt:P396 ?opac_sbn. }\n  OPTIONAL { ?contributor wdt:P4862 ?amazon. }\n  OPTIONAL { ?contributor wdt:P12430 ?storygraph. }\n  OPTIONAL { ?contributor wdt:P2397 ?youtube. }\n  OPTIONAL { ?contributor wdt:P569 ?birthDate. }\n  OPTIONAL { ?contributor wdt:P570 ?deathDate. }\n  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,' + cfg.langcode + '". }\n}'
        metadata_url = update_url_with_params(WIKIDATA_API_URL, {'format': 'json', 'query': query})
        data = fetch_until_successful(metadata_url)
        if 'results' not in data or 'bindings' not in data['results']:
            continue
        results = [obj for obj in data['results']['bindings'] if 'contributor' in obj and 'value' in obj['contributor']]
        for obj in results:
            contributor_id = get_wd_item_id(obj['contributor']['value'])
            if not ('contributorLabel' in obj and 'value' in obj['contributorLabel']):
                continue
            contributor = Author(friendly_name=obj['contributorLabel']['value'])
            if 'birthDate' in obj and 'value' in obj['birthDate']:
                contributor.birth_date = extract_year(obj['birthDate']['value'])
            if 'deathDate' in obj and 'value' in obj['deathDate']:
                contributor.death_date = extract_year(obj['deathDate']['value'])
            if 'olId' in obj and 'value' in obj['olId']:
                contributor.key = f'/authors/{obj['olId']['value']}'
            contributor.remote_ids['wikidata'] = contributor_id
            for id in ['viaf', 'bookbrainz', 'musicbrainz', 'goodreads', 'isni', 'imdb', 'lc_naf', 'librarything', 'librivox', 'project_gutenberg', 'opac_sbn', 'amazon', 'storygraph', 'youtube']:
                if id in obj and 'value' in obj[id]:
                    val = obj[id]['value']
                    if id == 'youtube' and val[0] != '@':
                        val = f'@{val}'
                    contributor.remote_ids[id] = val
            if contributor_id in map:
                book_ids = map[contributor_id]
                for book_id in book_ids:
                    imports[book_id].add_authors([contributor])

def process_all_books(cfg: LangConfig):
    imports: dict[str, BookRecord] = {}
    author_map: dict[str, list[str]] = {}
    for url in cfg.all_wikidata_category_urls:
        scrape_wikidata_api(url, cfg, imports, author_map)
    fix_contributor_data(imports, author_map, cfg)
    batch: list[BookRecord] = []
    for book in list(imports.values()):
        if cfg.exclude_book(book):
            continue
        batch.append(book)
    if batch:
        print_records(batch)

def main(ol_config: str):
    """
    :param str ol_config: Path to openlibrary.yml file
    """
    load_config(ol_config)
    for ws_language in ws_languages:
        process_all_books(ws_language)
if __name__ == '__main__':
    FnToCLI(main).run()

