API_MAX_ITEMS_PER_CALL = 10
API_MAX_WAIT_SECONDS = 0.9
AZ_OL_MAP = {
    'cover': 'covers',
    'title': 'title',
    'authors': 'authors',
    'publishers': 'publishers',
    'publish_date': 'publish_date',
    'number_of_pages': 'number_of_pages',
